 fun greet(c:Context):String{val h=Calendar.getInstance().get(Calendar.HOUR_OF_DAY);return f(c,if(h in 5..11)"gm" else if(h in 12..16)"ga" else if(h in 17..20)"ge" else "gn","n" to Store.name(c))}
 fun pre(c:Context,title:String):String{val x=title.lowercase();fun has(vararg k:String)=k.any{x.contains(it)}
  val key=if(has("wake","uth","jaag","उठ","जाग"))"pre_wake" else if(has("study","read","padh","पढ़","revision","exam"))"pre_study" else if(has("gym","workout","exercise","run","cardio","yoga","वर्कआउट","जिम"))"pre_workout" else if(has("code","coding","skill","practice","project","learn"))"pre_skill" else if(has("sleep","bed","neend","सोना"))"pre_sleep" else "pre_gen"
  return f(c,key,"t" to title)}
